/// <summary>
/// Select rows
/// </summary>
public void clicked()
{
    DMFEntity           dmfEntity;
    Common              staging, curStaging;
    SysDictTable        sysDictTable;
    FieldId             selectedFieldId;
    FieldId             recIdFieldId;
    int                 getPos;

    FormControl callerButton = any2Object(this) as FormControl; //Retrieves the button
    FormRun formRun = callerButton.formRun(); //Gets the running form

    FormDataSource curFormDS = formRun.dataSource();

    next clicked();

    DMFDefinitionGroupExecution defGroupExecutionTable = element.defGroupExecutionTable;
    getPos = curFormDS.getPosition();

    dmfEntity = DMFEntity::find(defGroupExecutionTable.Entity);

    if(dmfEntity.EntityType != DMFEntityTypes::CompositEntity)
    {
        sysDictTable = new SysDictTable(tableName2id(dmfEntity.EntityTable));

        if(sysDictTable)
        {
            staging     = sysDictTable.makeRecord();
            curStaging  = sysDictTable.makeRecord();

            selectedFieldId         = fieldName2id(tableName2id(dmfEntity.EntityTable), fieldStr(DMFEntityBaseTable, IsSelected));
            recIdFieldId            = fieldName2id(tableName2id(dmfEntity.EntityTable), fieldStr(DMFEntityBaseTable, RecId));

            MultiSelectionHelper selectionHelper = MultiSelectionHelper::construct();

            selectionHelper.parmDataSource(curFormDS);
            curStaging  = selectionHelper.getFirst();

            ttsbegin;
            while (curStaging)
            {
                select forupdate staging
                    where staging.(recIdFieldId) == curStaging.RecId
                    && staging.(selectedFieldId) == NoYes::No;

                if (staging)
                {
                    staging.(selectedFieldId) = NoYes::Yes;
                    staging.update();
                }

                curStaging = selectionHelper.getNext();
            }
            ttscommit;

            curFormDS.research(getPos);
        }
    }
}
